INSERT INTO `chunks` (`id`, `document_id`, `agent_id`, `ordinal`, `content`, `token_count`, `embedding`, `embed_model`, `embed_dims`, `metadata`, `created_at`) VALUES
(1, 21, 1, 0, 'Procurement Hub is a Saudi company established in 2016, specializing in procurement solutions and contract management. Its mission is \"Transforming Procurement into a Strategic Engine for Value Creation.\" It delivers end-to-end procurement solutions across the full lifecycle — from strategy and operating-model design through execution and continuous optimization — helping organizations strengthen governance, raise operational efficiency, and achieve sustainable value. Headquartered in Riyadh, Saudi Arabia. Website: procurementhub.sa. Main sections: Home, About Us, Products & Services, SPOC, Insights/Knowledge Center, Careers, Contact Us. The site is available in English and Arabic.', 173, , 'text-embedding-3-small', 1024, '{\"title\":\"About Procurement Hub\",\"document_id\":21,\"ordinal\":0}', '2026-07-16 10:42:48'),
(2, 22, 1, 0, 'Procurement Hub\'s Advisory services include: Procurement Assessment (evaluating procurement maturity across governance, processes and performance against leading practices); Local Content Support & Development (aligning with national localization requirements and developing supplier ecosystems); Category Management (strategic spend-category management using market intelligence and demand analysis); Supplier Relationship Management; Strategic Sourcing; Procurement Processes & Procedures Development; Procurement Department Operating Model design; Procurement Optimization; and Cost Management & Expenditure Analysis.', 155, , 'text-embedding-3-small', 1024, '{\"title\":\"Procurement Advisory Services\",\"document_id\":22,\"ordinal\":0}', '2026-07-16 10:42:48'),
(4, 24, 1, 0, 'Digital Solutions: a Vendor Hub platform, procurement analytics and executive dashboards, and performance analytics and reporting tools. The Saudi Procurement Operations Center (SPOC) is a centralized, scalable procurement operating model that offers structured governance frameworks, specialized teams with defined roles, advanced digital tools, standardized procedures across clients, and consistent performance standards to strengthen compliance.', 113, , 'text-embedding-3-small', 1024, '{\"title\":\"Digital Solutions & Saudi Procurement Operations Center (SPOC)\",\"document_id\":24,\"ordinal\":0}', '2026-07-16 10:42:50'),
(5, 25, 1, 0, 'Procurement Hub offers nine structured professional products, each built on practical implementation expertise and global leading practices: Monitor (performance tracking and oversight); Plan (strategic procurement planning and forecasting); Diagnostics (assessment and analysis tools); Local (local-content management and compliance); Optimize (efficiency and performance enhancement); Govern (governance frameworks and controls); Secure (risk management and security protocols); Costs (cost management and financial analysis); and Customize (tailored solution configuration).', 145, , 'text-embedding-3-small', 1024, '{\"title\":\"Professional Products (Monitor, Plan, Diagnostics, Local, Optimize, Govern, Secure, Costs, Customize)\",\"document_id\":25,\"ordinal\":0}', '2026-07-16 10:42:50'),
(6, 26, 1, 0, 'You can reach Procurement Hub at its office in Riyadh, Al Wadi District, Northern Ring Road Exit 6, Office 24, Saudi Arabia. Email: Info@procurementhub.sa. Phone: +966 55 524 5527 or 011 266 6628. WhatsApp: +966 55 524 5527. Website: procurementhub.sa. There is also a Careers section for open opportunities.', 77, , 'text-embedding-3-small', 1024, '{\"title\":\"Contact Procurement Hub\",\"document_id\":26,\"ordinal\":0}', '2026-07-16 10:42:50');
INSERT INTO `chunks` (`id`, `document_id`, `agent_id`, `ordinal`, `content`, `token_count`, `embedding`, `embed_model`, `embed_dims`, `metadata`, `created_at`) VALUES
(7, 27, 1, 0, 'بروكيورمنت هب شركة سعودية تأسست عام 2016 متخصصة في حلول المشتريات وإدارة العقود. رسالتها: \"تحويل المشتريات إلى محرك استراتيجي لخلق القيمة\". تقدّم حلولاً متكاملة عبر دورة الحياة الكاملة للمشتريات — من تصميم الاستراتيجية ونموذج التشغيل وحتى التنفيذ والتحسين المستمر — لمساعدة المؤسسات على تعزيز الحوكمة ورفع الكفاءة التشغيلية وتحقيق قيمة مستدامة. يقع مقرها في الرياض. الموقع: procurementhub.sa، ويتوفر بالعربية والإنجليزية.', 106, , 'text-embedding-3-small', 1024, '{\"title\":\"\\u0646\\u0628\\u0630\\u0629 \\u0639\\u0646 \\u0628\\u0631\\u0648\\u0643\\u064a\\u0648\\u0631\\u0645\\u0646\\u062a \\u0647\\u0628\",\"document_id\":27,\"ordinal\":0}', '2026-07-16 10:42:50'),
(8, 28, 1, 0, 'خدمات الاستشارات: تقييم نضج المشتريات، ودعم وتطوير المحتوى المحلي، وإدارة فئات الإنفاق، وإدارة علاقات الموردين، والتوريد الاستراتيجي، وتطوير إجراءات المشتريات، وتصميم نموذج تشغيل إدارة المشتريات، وتحسين المشتريات، وإدارة التكاليف وتحليل الإنفاق. عمليات المشتريات المُدارة: دعم التوريد الشامل، وإدارة دورة حياة العقود، وتأهيل الموردين وإدارة أدائهم، والشراء نيابةً عن الجهات. التحويل: إعادة تصميم العمليات وبناء القدرات وتحسين الأداء. الحلول الرقمية: منصة مركز الموردين، والتحليلات، ولوحات المعلومات التنفيذية.', 128, , 'text-embedding-3-small', 1024, '{\"title\":\"\\u062e\\u062f\\u0645\\u0627\\u062a \\u0628\\u0631\\u0648\\u0643\\u064a\\u0648\\u0631\\u0645\\u0646\\u062a \\u0647\\u0628\",\"document_id\":28,\"ordinal\":0}', '2026-07-16 10:42:51'),
(9, 29, 1, 0, 'تقدّم بروكيورمنت هب تسعة منتجات احترافية: Monitor (المتابعة والرقابة)، Plan (التخطيط والتنبؤ)، Diagnostics (التقييم والتحليل)، Local (إدارة المحتوى المحلي والامتثال)، Optimize (تحسين الكفاءة)، Govern (أطر الحوكمة والضوابط)، Secure (إدارة المخاطر)، Costs (إدارة التكاليف)، Customize (حلول مخصّصة). ومركز العمليات السعودي للمشتريات (SPOC) نموذج تشغيل مركزي قابل للتوسّع بحوكمة منظمة وفرق متخصصة وأدوات رقمية متقدمة وإجراءات موحّدة لتعزيز الامتثال.', 112, , 'text-embedding-3-small', 1024, '{\"title\":\"\\u0645\\u0646\\u062a\\u062c\\u0627\\u062a \\u0648\\u0645\\u0631\\u0643\\u0632 \\u0627\\u0644\\u0639\\u0645\\u0644\\u064a\\u0627\\u062a (SPOC)\",\"document_id\":29,\"ordinal\":0}', '2026-07-16 10:42:51'),
(10, 30, 1, 0, 'يمكنكم التواصل مع بروكيورمنت هب في مكتبها بالرياض، حي الوادي، مخرج ٦ الطريق الدائري الشمالي، مكتب ٢٤. البريد الإلكتروني: Info@procurementhub.sa. الهاتف: +966555245527 أو 0112666628. واتساب: +966555245527. الموقع: procurementhub.sa.', 58, , 'text-embedding-3-small', 1024, '{\"title\":\"\\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u0628\\u0631\\u0648\\u0643\\u064a\\u0648\\u0631\\u0645\\u0646\\u062a \\u0647\\u0628\",\"document_id\":30,\"ordinal\":0}', '2026-07-16 10:42:51'),
(16, 36, 1, 0, 'Procurement Hub helps public and private organizations navigate Saudi procurement and local-content regulations: assessing local-content maturity, preparing for Local Content Certificates, structuring category and sourcing strategies that respect preference rules, and operating efficiently on Etimad. Its advisory services, the \"Local\" and \"Govern\" products, and SPOC provide governance and compliance support. Note: Procurement Hub provides professional guidance; official, binding requirements come from the Ministry of Finance, LCGPA, and the Etimad platform.', 141, , 'text-embedding-3-small', 1024, '{\"title\":\"How Procurement Hub supports Saudi procurement compliance\",\"document_id\":36,\"ordinal\":0}', '2026-07-16 10:42:52');
INSERT INTO `chunks` (`id`, `document_id`, `agent_id`, `ordinal`, `content`, `token_count`, `embedding`, `embed_model`, `embed_dims`, `metadata`, `created_at`) VALUES
(17, 37, 1, 0, 'إرشاد عام (وليس استشارة قانونية). نظام المنافسات والمشتريات الحكومية هو النظام الرئيسي المنظّم لمشتريات الجهات الحكومية في المملكة، وقد صدر النظام المُحدّث عام 2019 وتشرف عليه وزارة المالية. ينظّم المنافسات والتعاقدات بين الجهات الحكومية والموردين بهدف تبسيط الإجراءات وتعزيز الشفافية والمنافسة العادلة وحماية المال العام ودعم الاقتصاد الوطني، وله لائحة تنفيذية. للاطلاع على المتطلبات المُلزمة والحالية يُرجى الرجوع إلى وزارة المالية وخبراء بروكيورمنت هب.', 114, , 'text-embedding-3-small', 1024, '{\"title\":\"\\u0646\\u0638\\u0627\\u0645 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0641\\u0633\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u0634\\u062a\\u0631\\u064a\\u0627\\u062a \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a\\u0629\",\"document_id\":37,\"ordinal\":0}', '2026-07-16 10:42:52'),
(21, 41, 1, 0, '# سياسة الخصوصية\n\n**آخر تحديث: [أدخل التاريخ]**\n\nتلتزم صرح المشتريات (\"نحن\"، \"لنا\"، \"الشركة\") بحماية خصوصية والبيانات الشخصية لكل من يزور موقعنا الإلكتروني، أو يستخدم خدماتنا، أو يتواصل معنا — بما في ذلك العملاء، والعملاء المحتملون، والمتقدمون للوظائف، وزوار الموقع الإلكتروني.\n\nتوضح سياسة الخصوصية هذه ما هي البيانات الشخصية التي نجمعها، ولماذا نجمعها، وكيف نستخدمها ونحميها، والحقوق التي تملكونها تجاهها. تصدر هذه السياسة وفقاً لـ**نظام حماية البيانات الشخصية** الصادر بالمرسوم الملكي رقم م/19 وتاريخ 9/2/1443هـ، المعدّل بالمرسوم الملكي رقم م/148 وتاريخ 5/9/1444هـ، ولائحته التنفيذية (يُشار إليهما معاً بـ\"**النظام**\")، الذي تشرف على تطبيقه **الهيئة السعودية للبيانات والذكاء الاصطناعي (\"سدايا\")**.\n\nإذا كانت لديكم أي استفسارات حول هذه السياسة أو كيفية تعاملنا مع بياناتكم، يرجى التواصل معنا عبر البيانات الموضحة في البند 12.\n\n---\n\n## 1. من نحن\n\nصرح المشتريات شركة سعودية تأسست عام 2016، متخصصة في تقديم حلول المشتريات وإدارة العقود وإدارة الموردين للجهات في مختلف أنحاء المملكة.\n\nلأغراض النظام، تُعد صرح المشتريات **جهة التحكم بالبيانات** فيما يتعلق بالبيانات الشخصية التي يتم جمعها من خلال هذا الموقع وخدماتنا.\n\n---\n\n## 2. نطاق هذه السياسة', 286, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":0}', '2026-07-16 11:06:54'),
(22, 41, 1, 1, 'ظام، تُعد صرح المشتريات **جهة التحكم بالبيانات** فيما يتعلق بالبيانات الشخصية التي يتم جمعها من خلال هذا الموقع وخدماتنا.\n\n---\n\n## 2. نطاق هذه السياسة\n\nتنطبق هذه السياسة على البيانات الشخصية التي نجمعها من خلال:\n\n- موقعنا الإلكتروني **procurementhub.sa** وجميع صفحاته ونطاقاته الفرعية\n- نظام حجز المواعيد والعروض التعريفية\n- نماذج التواصل والاستفسار\n- روبوت المحادثة الخاص بموقعنا الإلكتروني\n- المراسلات عبر البريد الإلكتروني معنا\n- أي تفاعل آخر تقومون به معنا كعميل، أو عميل محتمل، أو زائر\n\nلا تغطي هذه السياسة ممارسات المواقع الإلكترونية الخارجية التي قد نرتبط بها، ولا الجهات الخارجية التي تجمع بياناتكم بشكل مستقل (على سبيل المثال، عند تفاعلكم معنا عبر لينكد إن، تنطبق سياسة الخصوصية الخاصة بتلك المنصة على ذلك التفاعل).\n\n---\n\n## 3. البيانات الشخصية التي نجمعها\n\nاعتماداً على طريقة تفاعلكم معنا، قد نجمع:', 202, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":1}', '2026-07-16 11:06:54'),
(23, 41, 1, 2, 'ينكد إن، تنطبق سياسة الخصوصية الخاصة بتلك المنصة على ذلك التفاعل).\n\n---\n\n## 3. البيانات الشخصية التي نجمعها\n\nاعتماداً على طريقة تفاعلكم معنا، قد نجمع:\n\n| الفئة | أمثلة |\n|---|---|\n| **بيانات الهوية** | الاسم الكامل، المسمى الوظيفي، اسم الجهة |\n| **بيانات التواصل** | البريد الإلكتروني، رقم الهاتف، عنوان الجهة |\n| **بيانات الحجز** | تاريخ ووقت الموعد، الغرض من اللقاء، الملاحظات المقدمة عند حجز عرض تعريفي |\n| **بيانات المراسلات** | الرسائل التي ترسلونها إلينا عبر نماذج التواصل، أو روبوت المحادثة، أو البريد الإلكتروني، بما في ذلك محتواها |\n| **البيانات التقنية** | عنوان IP، نوع المتصفح، نوع الجهاز، الموقع العام (على مستوى المدينة/الدولة)، الصفحات التي تمت زيارتها، الموقع المُحيل |\n| **بيانات ملفات تعريف الارتباط والتتبع** | كما هو موضح في سياسة ملفات تعريف الارتباط الخاصة بنا، بما في ذلك ملفات تعريف الارتباط التحليلية والوظيفية |', 210, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":2}', '2026-07-16 11:06:54'),
(24, 41, 1, 3, '**بيانات ملفات تعريف الارتباط والتتبع** | كما هو موضح في سياسة ملفات تعريف الارتباط الخاصة بنا، بما في ذلك ملفات تعريف الارتباط التحليلية والوظيفية |\n\nنحن **لا** نقوم عن قصد بجمع البيانات الشخصية الحساسة (كالبيانات الصحية، أو الانتماء الديني أو السياسي، أو البيانات الحيوية) من خلال هذا الموقع. وإذا قمتم بتقديم مثل هذه البيانات طواعيةً (على سبيل المثال، ضمن حقل نصي حر)، فسنتعامل معها وفق الضمانات الإضافية التي يتطلبها النظام للبيانات الحساسة، ونشجعكم على عدم مشاركة مثل هذه المعلومات معنا ما لم يكن ذلك ضرورياً.\n\n---\n\n## 4. كيفية جمع بياناتكم\n\n- **مباشرة منكم** — عند تعبئة نموذج تواصل، أو حجز موعد عرض تعريفي، أو التحدث مع روبوت المحادثة، أو مراسلتنا عبر البريد الإلكتروني\n- **بشكل تلقائي** — من خلال ملفات تعريف الارتباط والتقنيات المشابهة أثناء تصفحكم لموقعنا (انظر سياسة ملفات تعريف الارتباط)\n- **من جهات خارجية** — في حالات محدودة، مثل قيام أحد الزملاء بإحالتكم إلينا وتقديم بيانات التواصل الخاصة بكم نيابةً عنكم\n\n---\n\n## 5. لماذا نعالج بياناتكم، وأساسنا النظامي\n\nبموجب النظام، لا نقوم بمعالجة البيانات الشخصية إلا عند توفر أساس نظامي صحيح لذلك. ونعتمد على الأسس التالية:', 270, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":3}', '2026-07-16 11:06:54');
INSERT INTO `chunks` (`id`, `document_id`, `agent_id`, `ordinal`, `content`, `token_count`, `embedding`, `embed_model`, `embed_dims`, `metadata`, `created_at`) VALUES
(25, 41, 1, 4, '5. لماذا نعالج بياناتكم، وأساسنا النظامي\n\nبموجب النظام، لا نقوم بمعالجة البيانات الشخصية إلا عند توفر أساس نظامي صحيح لذلك. ونعتمد على الأسس التالية:\n\n| الغرض | الأساس النظامي |\n|---|---|\n| الرد على استفساراتكم وطلبات الحجز | ضروري لاتخاذ إجراءات بناءً على طلبكم تمهيداً للتعاقد معكم |\n| تقديم وإدارة خدماتنا للعملاء الحاليين | تنفيذ العقد |\n| إرسال تأكيدات وتذكيرات المواعيد | تنفيذ العقد / بناءً على طلبكم الصريح |\n| تحسين موقعنا الإلكتروني وخدماتنا | مصلحتنا المشروعة، بعد الموازنة مع حقوقكم، بما لا يتعارض مع حقوقكم وحرياتكم الأساسية |\n| إرسال الرسائل التسويقية | موافقتكم الصريحة، والتي يمكنكم سحبها في أي وقت |\n| الامتثال للالتزامات النظامية والتنظيمية | الامتثال لالتزام نظامي بموجب الأنظمة السعودية |\n| استخدام ملفات تعريف الارتباط والتقنيات غير الضرورية | موافقتكم، المقدمة عبر شريط موافقة ملفات تعريف الارتباط |\n\nلا نستخدم بياناتكم الشخصية لاتخاذ قرارات آلية أو للتنميط الذي قد يُحدث آثاراً نظامية أو مؤثرة بشكل مماثل عليكم.\n\n---\n\n## 6. ملفات تعريف الارتباط والتقنيات المشابهة', 247, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":4}', '2026-07-16 11:06:54'),
(26, 41, 1, 5, 'ناتكم الشخصية لاتخاذ قرارات آلية أو للتنميط الذي قد يُحدث آثاراً نظامية أو مؤثرة بشكل مماثل عليكم.\n\n---\n\n## 6. ملفات تعريف الارتباط والتقنيات المشابهة\n\nيستخدم موقعنا الإلكتروني ملفات تعريف الارتباط والتقنيات المشابهة لضمان عمل الموقع بشكل صحيح، وتذكّر تفضيلاتكم، وفهم كيفية استخدام الزوار لموقعنا. نستخدم أداة لإدارة موافقة ملفات تعريف الارتباط تتيح لكم مراجعة والتحكم في فئات ملفات تعريف الارتباط التي تسمحون بها، بخلاف تلك الضرورية بشكل أساسي لعمل الموقع.\n\nيمكنكم إدارة تفضيلات ملفات تعريف الارتباط الخاصة بكم في أي وقت من خلال أيقونة إعدادات ملفات تعريف الارتباط المتوفرة على موقعنا، أو من خلال إعدادات المتصفح الخاص بكم. للاطلاع على التفاصيل الكاملة حول ملفات تعريف الارتباط المحددة التي نستخدمها والغرض منها ومدتها، يرجى الرجوع إلى لوحة تفضيلات ملفات تعريف الارتباط المتوفرة على هذا الموقع.\n\n---\n\n## 7. مع من نشارك بياناتكم\n\nنحن لا نبيع بياناتكم الشخصية. نشارك البيانات الشخصية فقط مع الفئات التالية من الجهات، وفقط بالقدر الضروري:', 234, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":5}', '2026-07-16 11:06:54'),
(27, 41, 1, 6, 'ا الموقع.\n\n---\n\n## 7. مع من نشارك بياناتكم\n\nنحن لا نبيع بياناتكم الشخصية. نشارك البيانات الشخصية فقط مع الفئات التالية من الجهات، وفقط بالقدر الضروري:\n\n- **مزودو الخدمات الذين يعالجون البيانات نيابة عنا**، بموجب اتفاقيات مكتوبة تُلزمهم بحماية بياناتكم بما يتوافق مع النظام، بما في ذلك:\n - مزودو خدمات استضافة وبنية الموقع الإلكتروني التحتية\n - مزودو خدمة إرسال البريد الإلكتروني، المستخدمة حصراً لإرسال المراسلات التشغيلية مثل تأكيدات المواعيد\n - مزود نظام حجز المواعيد لدينا\n - مزود روبوت المحادثة الخاص بموقعنا\n - مزودو خدمات التحليلات وإدارة موافقة ملفات تعريف الارتباط\n- **المستشارون المهنيون** (القانونيون، والمحاسبون، والماليون) عند الضرورة لعملياتنا التجارية المشروعة\n- **الجهات التنظيمية والسلطات العامة**، حيثما كنا ملزمين نظاماً بالإفصاح عن البيانات (على سبيل المثال، لسدايا أو غيرها من السلطات السعودية المختصة)، وسنقوم بتوثيق وتقييم مثل هذه الطلبات وفقاً للائحة التنفيذية\n- **جهة خلف قانونية**، في حال الاندماج أو الاستحواذ أو بيع أصول العمل، مع خضوعها لذات الحماية الموضحة في هذه السياسة\n\n---\n\n## 8. النقل الدولي للبيانات\n\nقد يقوم بعض مزودي الخدمات المذكورين في البند 7 بمعالجة البيانات الشخصية باستخدام بنية تحتية موجودة خارج المملكة العربية السعودية.', 292, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":6}', '2026-07-16 11:06:54'),
(28, 41, 1, 7, 'نقل الدولي للبيانات\n\nقد يقوم بعض مزودي الخدمات المذكورين في البند 7 بمعالجة البيانات الشخصية باستخدام بنية تحتية موجودة خارج المملكة العربية السعودية.\n\nعندما ننقل البيانات الشخصية خارج المملكة، فإننا نفعل ذلك فقط عند استيفاء متطلبات النظام الخاصة بالنقل عبر الحدود — بما في ذلك، بحسب الحال، التحقق من توفر مستوى حماية كافٍ في الجهة المستقبِلة، أو وضع ضمانات تعاقدية معتمدة من سدايا، والتأكد من أن النقل لا يُخل بقدرتكم على ممارسة حقوقكم بموجب النظام أو بالمصالح الوطنية للمملكة.\n\nنحتفظ بسجل لمعالجي البيانات لدينا والمواقع التي تتم فيها معالجة البيانات، وهو متاح عند الطلب كما هو موضح في البند 12.\n\n---\n\n## 9. مدة الاحتفاظ بالبيانات\n\nنحتفظ بالبيانات الشخصية فقط للمدة اللازمة لتحقيق الأغراض التي جُمعت من أجلها، بما في ذلك الوفاء بأي متطلبات نظامية أو محاسبية أو رقابية بموجب الأنظمة السعودية.\n\n- **بيانات الحجز والاستفسارات**: تُحفظ طوال مدة تعاملنا معكم، ولفترة معقولة بعد ذلك لمعالجة أي أمور متعلقة بالمتابعة أو الجوانب النظامية أو التعاقدية\n- **بيانات موافقة التسويق**: تُحفظ إلى حين سحبكم للموافقة\n- **بيانات ملفات تعريف الارتباط**: تُحفظ وفقاً للمدة المحددة لكل ملف تعريف ارتباط في أداة إدارة الموافقة الخاصة بنا\n\nعندما لا تعود البيانات الشخصية لازمة، نقوم بحذفها أو إخفاء هويتها بشكل آمن.\n\n---', 300, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":7}', '2026-07-16 11:06:54'),
(29, 41, 1, 8, 'للمدة المحددة لكل ملف تعريف ارتباط في أداة إدارة الموافقة الخاصة بنا\n\nعندما لا تعود البيانات الشخصية لازمة، نقوم بحذفها أو إخفاء هويتها بشكل آمن.\n\n---\n\n## 10. كيف نحمي بياناتكم\n\nنطبق تدابير تقنية وتنظيمية مناسبة لحماية البيانات الشخصية من الوصول غير المصرح به، أو الإفصاح، أو التعديل، أو الإتلاف، بما يتوافق مع متطلبات النظام الخاصة بأمن البيانات. وتشمل هذه التدابير:\n\n- تشفير نقل البيانات (HTTPS/TLS) عبر موقعنا الإلكتروني\n- ضوابط للوصول تقصر الاطلاع على البيانات الشخصية على الموظفين المصرح لهم فقط\n- المراجعة الدورية لممارساتنا الأمنية ومزودي الخدمات الخارجيين\n- إجراءات داخلية لتحديد وتقييم أي اختراق محتمل للبيانات والاستجابة له، بما في ذلك إبلاغ سدايا والأشخاص المتضررين دون تأخير غير مبرر حيثما يتطلب النظام ذلك\n\nلا توجد وسيلة لنقل أو تخزين البيانات آمنة بنسبة 100%، وبينما نعمل جاهدين لحماية بياناتكم الشخصية، فإننا لا نستطيع ضمان أمنها المطلق.\n\n---\n\n## 11. حقوقكم بموجب النظام\n\nبصفتكم صاحب بيانات، لكم الحقوق التالية فيما يتعلق ببياناتكم الشخصية:', 239, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":8}', '2026-07-16 11:06:54');
INSERT INTO `chunks` (`id`, `document_id`, `agent_id`, `ordinal`, `content`, `token_count`, `embedding`, `embed_model`, `embed_dims`, `metadata`, `created_at`) VALUES
(30, 41, 1, 9, 'تكم الشخصية، فإننا لا نستطيع ضمان أمنها المطلق.\n\n---\n\n## 11. حقوقكم بموجب النظام\n\nبصفتكم صاحب بيانات، لكم الحقوق التالية فيما يتعلق ببياناتكم الشخصية:\n\n- **الحق في العلم** — معرفة الأساس النظامي والغرض من جمع بياناتكم الشخصية\n- **حق الوصول** — طلب نسخة من البيانات الشخصية التي نحتفظ بها عنكم\n- **حق التصحيح** — طلب تصحيح البيانات الشخصية غير الدقيقة أو غير المكتملة\n- **حق الحذف/الإتلاف** — طلب إتلاف بياناتكم الشخصية عندما لا تعود لازمة للغرض الذي جُمعت من أجله، مع مراعاة أي التزامات نظامية بالاحتفاظ بها\n- **حق سحب الموافقة** — سحب أي موافقة سبق أن قدمتموها، في أي وقت، دون أن يؤثر ذلك على مشروعية المعالجة قبل السحب\n- **حق تقييد المعالجة** — في حالات معينة\n- **الحق في الإبلاغ عن اختراق البيانات** — عندما يُحتمل أن يتسبب الاختراق بضرر جسيم لكم أو لبياناتكم\n\nلممارسة أي من هذه الحقوق، يرجى التواصل معنا عبر البيانات الموضحة في البند 12. سنقوم بالرد على طلبكم خلال المدة التي يتطلبها النظام ولائحته التنفيذية. قد نحتاج للتحقق من هويتكم قبل معالجة بعض الطلبات.\n\nإذا رأيتم أننا لم نتعامل مع بياناتكم الشخصية وفقاً للنظام، فمن حقكم تقديم شكوى إلى سدايا.\n\n---\n\n## 12. تواصلوا معنا', 270, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":9}', '2026-07-16 11:06:54'),
(31, 41, 1, 10, 'من هويتكم قبل معالجة بعض الطلبات.\n\nإذا رأيتم أننا لم نتعامل مع بياناتكم الشخصية وفقاً للنظام، فمن حقكم تقديم شكوى إلى سدايا.\n\n---\n\n## 12. تواصلوا معنا\n\nإذا كانت لديكم أي استفسارات حول سياسة الخصوصية هذه، أو ترغبون بممارسة حقوقكم، أو لديكم أي ملاحظة حول كيفية تعاملنا مع بياناتكم الشخصية، يرجى التواصل معنا:\n\n**صرح المشتريات**\nالبريد الإلكتروني: [أدخل بريد الخصوصية، مثال: privacy@procurementhub.sa]\nالعنوان: [أدخل عنوان الجهة الرسمي]\nالهاتف: [أدخل رقم الهاتف]\n\n---\n\n## 13. الرسائل التسويقية\n\nإذا كنتم قد وافقتم على تلقي رسائل تسويقية منا، يمكنكم سحب موافقتكم وإلغاء الاشتراك في أي وقت باستخدام رابط إلغاء الاشتراك في أي رسالة تسويقية نرسلها، أو من خلال التواصل معنا مباشرة. نحن لا نستخدم البيانات الشخصية الحساسة لأغراض التسويق، ولا نبيع أو نؤجر بيانات التواصل الخاصة بكم لجهات خارجية لأغراضها التسويقية.\n\n---\n\n## 14. خصوصية الأطفال\n\nموقعنا الإلكتروني وخدماتنا موجهة للاستخدام التجاري وليست موجهة للأفراد دون سن 18 عاماً. نحن لا نقوم عن قصد بجمع بيانات شخصية من الأطفال. إذا اعتقدتم أن طفلاً قد زوّدنا ببيانات شخصية، يرجى التواصل معنا لاتخاذ الإجراء المناسب.\n\n---\n\n## 15. التعديلات على هذه السياسة', 275, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":10}', '2026-07-16 11:06:54'),
(32, 41, 1, 11, 'يانات شخصية من الأطفال. إذا اعتقدتم أن طفلاً قد زوّدنا ببيانات شخصية، يرجى التواصل معنا لاتخاذ الإجراء المناسب.\n\n---\n\n## 15. التعديلات على هذه السياسة\n\nقد نقوم بتحديث سياسة الخصوصية هذه من وقت لآخر لتعكس التغيرات في ممارساتنا، أو خدماتنا، أو الأنظمة المعمول بها، بما في ذلك أي إرشادات مستقبلية تصدرها سدايا. سننشر أي تحديثات على هذه الصفحة مع تاريخ \"آخر تحديث\" محدّث. نشجعكم على مراجعة هذه السياسة بشكل دوري.\n\n---\n\n## 16. القانون الحاكم\n\nتخضع سياسة الخصوصية هذه لأنظمة المملكة العربية السعودية، بما في ذلك نظام حماية البيانات الشخصية ولائحته التنفيذية. وتخضع أي نزاعات تنشأ عن هذه السياسة للاختصاص القضائي الحصري للمحاكم المختصة في المملكة العربية السعودية.\n\n---\n\n*هذه السياسة متوفرة باللغتين العربية والإنجليزية. في حال وجود أي تعارض بين النسختين، تكون النسخة العربية هي السارية.*', 196, , 'text-embedding-3-small', 1024, '{\"title\":\"privacy policy\",\"document_id\":41,\"ordinal\":11}', '2026-07-16 11:06:54'),
(33, 42, 1, 0, 'this organization\'s name is procurement hub , in arabic: صرح المشتريات', 18, , 'text-embedding-3-small', 1024, '{\"title\":\"Company name\",\"document_id\":42,\"ordinal\":0}', '2026-07-19 06:49:19'),
(34, 43, 1, 0, 'For submitting queries or details about anything you can approach us on the contact us link : https://procurementhub.sa/contact-us/\nFor vendor hub demo book your slot on this link : http://procurementhub.sa/book-demo \nfor Online Business evaluation of Maturity assessment portal link : https://procurementhub.sa/assessment/', 81, , 'text-embedding-3-small', 1024, '{\"title\":\"some important links\",\"document_id\":43,\"ordinal\":0}', '2026-08-18 08:49:30');
